    bool ok = !std::strcmp(g_log, "INTRO_FIRST;WELL_DONE_10;WELL_DONE_REPEAT;walk;LEAVING_HIT;run;WELL_DONE_REPEAT;walk;fade;") && !a.PlayerAttackedFans;
